import { BrowserRouter as Router, Route, Routes, Navigate } from "react-router-dom";
import './SignUp/SignUp.css';
import './LogIn/logIn.css';
import './HomePage/HomePage.css';
import { useState } from 'react';

import SignUp from './SignUp/SignUp.js';
import LogIn from './LogIn/logIn.js';
import HomePage from './HomePage/HomePage.js';

function App() {
  const [activeUser, setActiveUser] = useState('');
  const [usersList, setUsersList] = useState('');
  
  return (
    <div className="App">
      <header className="App-header">
        <Router>
          <Routes>
            <Route path="" element={<LogIn setActiveUser={setActiveUser} usersList={usersList} />} />
            <Route path="/SignUp" element={<SignUp usersList={usersList} setUsersList={setUsersList} />} />
            <Route path="/HomePage" element={activeUser ? <HomePage activeUser={activeUser} /> : <Navigate to="/ " />} />
          </Routes>
        </Router>
      </header>
    </div>
  );
}

export default App;
